 document.addEventListener('click',event=>{const target=event.target.closest('[data-cmd],[data-command-task],[data-command-resource]');if(!target)return;if(target.dataset.commandTask){if(document.body.dataset.page==='command-replay'){const frames=data.history,i=replayIndex<0?frames.length-1:Math.min(replayIndex,frames.length-1),t=frames[i]?.state.tasks.find(t=>t.id===target.dataset.commandTask);if(t)modal('<h2>'+e(t.title)+'</h2><p>'+e(t.description)+'</p><p>状态：'+e(statusNames[t.status])+'；作业 '+(t.progress||0)+'/'+t.workMinutes+' 分钟</p><p class="hint">历史快照，只读查看。</p>');}else taskDialog('report-task',target.dataset.commandTask);return;}if(target.dataset.commandResource){workTab='dispatch';window.navigate('command');return;}handleClick(target.dataset).catch(err=>message(err.message));});
