 let dragStep=null;
 document.addEventListener('dragstart',event=>{const row=event.target.closest('[data-step-index]');if(row){captureSteps();dragStep=Number(row.dataset.stepIndex);event.dataTransfer.effectAllowed='move';}});
 document.addEventListener('dragover',event=>{if(dragStep!==null&&event.target.closest('[data-step-index]'))event.preventDefault();});
 document.addEventListener('drop',event=>{const row=event.target.closest('[data-step-index]');if(dragStep===null||!row)return;event.preventDefault();const to=Number(row.dataset.stepIndex),slots=draftSteps.map(s=>s.at).sort((a,b)=>a-b),moved=draftSteps.splice(dragStep,1)[0];draftSteps.splice(to,0,moved);draftSteps=draftSteps.map((s,k)=>({...s,at:slots[k]}));dragStep=null;document.querySelector('#command-step-editor').innerHTML=stepEditor();});
