 FloodGeoScene.onAnnotation?.(annotation=>{if(document.body.dataset.page==='command-replay'){message('回放仅供查看。');return;}const p=annotation.center||annotation.geometry?.coordinates?.flat(Infinity).slice(0,2);const nodes=Object.entries(FloodGeoScene.getPoints());const node=nodes.sort((a,b)=>Math.hypot(a[1][0]-p[0],a[1][1]-p[1])-Math.hypot(b[1][0]-p[0],b[1][1]-p[1]))[0]?.[0]||'S';dispatch({type:'annotate',annotation:{...annotation,node,text:'演练地图标绘',title:'演练地图标绘',kind:annotation.geometry?.type==='Point'?'point':annotation.geometry?.type==='LineString'?'line':'polygon'}});});
