 setTimeout(async()=>{try{const saved=JSON.parse(sessionStorage.getItem('flood-room-session-v1')||'null');if(saved){const r=await api('/api/state?code='+encodeURIComponent(saved.code),null,saved.token);connect({...r,token:saved.token,role:r.role||saved.role},saved.name);}}catch{try{sessionStorage.removeItem('flood-room-session-v1');}catch{}}},0);
 return {pages,isPage,view,decorate,loadLocal,commandState,getState:()=>data,getRole:()=>role,getMode:()=>connection?'room':'local',showWorkTab:value=>{if(['tasks','orders','dispatch','reports','discussion'].includes(value)){workTab=value;window.navigate(({tasks:'command',dispatch:'command-dispatch',orders:'command-orders',reports:'command-reports',discussion:'command-discussion'})[value]);}},dispatch,save:()=>connection?message('房间数据由协同服务保存。'):(storage(),message('演练已保存到本机。')),exportDocx:wordReport,reportHtml,stop:stopTimers};
