/* Reciprocal script challenges use separate local rounds and exchangeable evidence. */
window.FloodScriptDuel=(()=>{
 'use strict';
 const C=FloodCommandEngine,U=FloodCommandUI,K='flood-script-duel-v1',copy=x=>JSON.parse(JSON.stringify(x));
 const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const uid=p=>p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),assert=(v,m)=>{if(!v)throw Error(m);};
 const clean=s=>{const v=copy(s);v.history=[];return v;};
 const stable=x=>JSON.stringify(x,(_,v)=>v&&typeof v==='object'&&!Array.isArray(v)?Object.fromEntries(Object.keys(v).sort().map(k=>[k,v[k]])):v);
 const empty=()=>({version:1,match:null,side:'A',own:null,opponent:null,ownResult:null,opponentResult:null,active:null});
 let store=empty(),pending=null,loadError=false,lastStored=null;try{lastStored=localStorage.getItem(K);}catch{}
 const btn=(label,action,attrs='',cls='')=>`<button class="${cls}" data-duel="${action}" ${attrs}>${label}</button>`;
 const opposite=side=>side==='A'?'B':'A',team=side=>store.match?.teams[side]||side;
 function validateMatch(m){assert(m&&/^[-\w]{1,80}$/.test(m.id)&&m.rules===1,'对战编号或规则不正确');assert(typeof m.title==='string'&&m.title.trim()&&m.title.length<=80,'对战名称不正确');assert(m.teams&&['A','B'].every(k=>typeof m.teams[k]==='string'&&m.teams[k].trim()&&m.teams[k].length<=40)&&m.teams.A!==m.teams.B,'请设置两个不同的队名');return {id:m.id,title:m.title,teams:{A:m.teams.A,B:m.teams.B},rules:1};}
 function definition(library,scriptId){const base=C.create();base.library=copy(library);base.units=[];base.history=[];base.run.scriptId=scriptId;const v=C.validate(base);assert(v.ok,v.error);const script=v.state.library.scripts.find(s=>s.id===scriptId);assert(script&&v.state.library.scripts.length===1,'题包必须只包含一个选定脚本');return {library:v.state.library,scriptId};}
 function expected(packet){const script=packet.library.scripts[0];return script.steps.map(step=>{const src=step.scenarioId?packet.library.scenarios.find(s=>s.id===step.scenarioId).task:step.task;return {...copy(src),step:step.id,at:step.at,...(step.questionId?{questionId:step.questionId}:{})};});}
 function metrics(packet,state){
  const tasks=expected(packet);let weight=0,done=0;const times=[];
  assert(state.tasks.length<=tasks.length,'战报包含脚本之外的任务');
  for(const t of state.tasks){const source=tasks.find(q=>'script:'+q.step===t.source);assert(source,'战报包含额外任务');assert(state.tasks.filter(a=>a.source===t.source).length===1,'战报任务重复');assert(t.createdAt===source.at,'任务投放时刻与脚本不符');for(const k of ['title','description','node','role','requirements','workMinutes','deadline','weight','questionId','fileIds'])assert(stable(t[k]??null)===stable(source[k]??null),'任务条件已被修改');}
  for(const t of tasks){weight+=t.weight;const actual=state.tasks.find(a=>a.source==='script:'+t.step);if(actual?.status==='completed'&&actual.completedAt<=actual.deadlineAt){done+=t.weight;times.push(actual.completedAt);}}
  const full=done===weight&&state.tasks.length===tasks.length&&state.run.firedSteps.length===tasks.length;
  return {rate:weight?done/weight:0,total:tasks.length,onTime:times.length,full,completionTime:full?Math.max(...times):null,spent:state.spent};
 }
 function runProof(packet,raw,side,kind){const v=C.validate(clean(raw));assert(v.ok,v.error);const s=v.state;assert(s.run.status==='ended'&&s.run.scriptId===packet.scriptId,'请先结束本轮，战报须对应原脚本');assert(stable(s.library)===stable(packet.library),'战报脚本或资源定义与原题不一致');const context=s.duelContext;assert(context&&context.matchId===packet.match.id&&context.challengeId===packet.id&&context.side===side&&context.kind===kind,'战报来源与当前对战不符');metrics(packet,s);return s;}
 function validatePacket(raw,requireProof=true){assert(raw?.kind==='flood-script-duel-challenge'&&raw.version===1&&/^[-\w]{1,80}$/.test(raw.id)&&['A','B'].includes(raw.author),'请选择双向脚本对战题包');const m=validateMatch(raw.match),d=definition(raw.library,raw.scriptId),packet={kind:raw.kind,version:1,id:raw.id,match:m,author:raw.author,...d};if(raw.referenceState||requireProof){packet.referenceState=runProof(packet,raw.referenceState,raw.author,'author');assert(metrics(packet,packet.referenceState).full,'出题方尚未按期完成全部脚本任务，不能发布');}return packet;}
 function result(packet,raw,side){assert(raw?.kind==='flood-script-duel-result'&&raw.version===1&&raw.matchId===packet.match.id&&raw.challengeId===packet.id&&raw.solver===side&&raw.author===packet.author,'战报不属于本场对战或对应脚本');return {kind:raw.kind,version:1,matchId:raw.matchId,challengeId:raw.challengeId,solver:side,author:raw.author,state:runProof(packet,raw.state,side,'challenge')};}
 function commit(next){const serialized=JSON.stringify(next);assert(serialized.length<=4500000,'对战记录较大，请先导出本轮文件；可减少资料附件后重新编题');try{assert(localStorage.getItem(K)===lastStored,'另一页面已更新本场对战，请刷新后继续，避免覆盖进度');localStorage.setItem(K,serialized);lastStored=serialized;}catch(err){throw Error(err.message.includes('另一页面')?err.message:'本机空间不足，对战记录未保存；请先导出重要记录');}store=next;loadError=false;}
 try{const raw=JSON.parse(localStorage.getItem(K)||'null');if(raw){assert(raw.version===1&&['A','B'].includes(raw.side),'对战记录格式错误');if(raw.match)raw.match=validateMatch(raw.match);if(raw.own)raw.own=validatePacket(raw.own,!!raw.own.referenceState);if(raw.opponent)raw.opponent=validatePacket(raw.opponent);if(raw.ownResult)raw.ownResult=result(raw.opponent,raw.ownResult,raw.side);if(raw.opponentResult)raw.opponentResult=result(raw.own,raw.opponentResult,opposite(raw.side));if(raw.active){assert(['author','challenge'].includes(raw.active.kind),'对战轮次不正确');const v=C.validate(clean(raw.active.state));assert(v.ok,v.error);raw.active.state=v.state;}store=raw;}}catch{loadError=true;}
 function local(){assert(U.getMode()==='local'&&U.getRole()==='director','请先退出协作房间并切换到本机导调身份，独立完成对战轮次');assert(typeof state==='undefined'||state.assessment?.phase!=='active','请先保存退出当前考核');}
 function current(){return !!store.active&&U.getState().duelContext?.attemptId===store.active.id;}
 function guard(action){if(!current())return null;if(localStorage.getItem(K)!==lastStored)return '另一页面已更新本场对战，请刷新后继续';return ['run-start','trigger-step','run-step','inject','library-upsert','library-remove','weather','evaluate'].includes(action.type)?'对战轮次中脚本、投放时刻和资源已锁定；请按原任务处置。若要另开演练，先在对战页封存或退出本轮。':null;}
 function observe(s){if(!store.active||s.duelContext?.attemptId!==store.active.id)return;const next=copy(store);next.active.state=clean(s);try{commit(next);}catch(err){window.toast?.(err.message);}}
 function banner(){if(!current())return '';return `<section class="duel-banner"><div><b>${e(store.match.title)} · ${e(team(store.side))}</b><small>${store.active.kind==='author'?'出题方自测：须按期完成全部节点，才能发布题包。':'正在解决对方脚本；固定投放时间和资源条件。'}</small></div><button data-nav="command-duel">返回对战页 / 封存结果</button></section>`;}
 function begin(kind,scriptId){
  local();assert(store.match,'请先创建或导入对战邀请');const next=copy(store);let packet;
  if(kind==='author'){const library=copy(U.getState().library);library.scripts=library.scripts.filter(s=>s.id===scriptId);packet={kind:'flood-script-duel-challenge',version:1,id:uid('question'),match:next.match,author:next.side,...definition(library,scriptId)};next.own=packet;next.opponentResult=null;}else{assert(next.opponent,'请先导入对方题包');packet=next.opponent;next.ownResult=null;}
  const base=C.create();base.library=copy(packet.library);base.history=[];const r=C.apply(base,{type:'run-start',scriptId:packet.scriptId},'director');assert(r.ok,r.error);const id=uid('attempt');base.duelContext={attemptId:id,challengeId:packet.id,matchId:next.match.id,side:next.side,kind};next.active={id,kind,state:clean(base)};
  const previous=copy(store);commit(next);try{U.loadLocal(base);}catch(err){commit(previous);throw err;}window.navigate('command');window.toast?.('对战轮次已开始，请进入力量派遣处理脚本任务');
 }
 async function finish(){local();assert(current(),'当前演练与对战轮次不同，请先恢复本轮');const packet=store.active.kind==='author'?store.own:store.opponent;if(U.getState().run.status!=='ended'){if(store.active.kind==='author')assert(metrics(packet,U.getState()).full,'自测须按期完成全部任务，包括尚未投放的节点');assert(await U.dispatch({type:'run-end'}),'无法结束本轮');}const next=copy(store),s=clean(U.getState());if(store.active.kind==='author'){assert(metrics(packet,s).full,'自测未按期完成全部任务，请调整脚本后重新自测');next.own={...packet,referenceState:s};validatePacket(next.own);}else next.ownResult=result(packet,{kind:'flood-script-duel-result',version:1,matchId:store.match.id,challengeId:packet.id,solver:store.side,author:packet.author,state:s},store.side);next.active=null;commit(next);window.navigate('command-duel');window.toast?.('本轮证据已封存，可导出交换');}
 function scoreboard(){if(!store.ownResult||!store.opponentResult)return '<p class="hint">双方均封存并交换战报后，再显示双向对照。只完成单边挑战时不判胜负。</p>';const rows=[{side:store.side,packet:store.opponent,proof:store.ownResult},{side:opposite(store.side),packet:store.own,proof:store.opponentResult}].map(row=>{const m=metrics(row.packet,row.proof.state),ref=metrics(row.packet,row.packet.referenceState);return {...row,m,ref,index:m.full ? 0.6*(m.completionTime+1)/(ref.completionTime+1)+.4*(m.spent+1)/(ref.spent+1):null};});const [a,b]=rows;let verdict;if(Math.abs(a.m.rate-b.m.rate)>.000001)verdict=`${team(a.m.rate>b.m.rate?a.side:b.side)} 按期完成权重比例更高`;else if(!a.m.full||!b.m.full)verdict='双方均未按期完成全部目标，完成比例相同，本轮暂不判胜';else if(Math.abs(a.index-b.index)<.001)verdict='双方相对表现相当，本轮平局';else verdict=`${team(a.index<b.index?a.side:b.side)} 本轮相对表现更优`;return `<p class="duel-verdict">${e(verdict)}</p><div class="table-wrap"><table><thead><tr><th>解题方</th><th>按期完成</th><th>实际首次完成</th><th>实际投入</th><th>相对作者自测指数 ↓</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${e(team(r.side))}</td><td>${(r.m.rate*100).toFixed(1)}%（${r.m.onTime}/${r.m.total}任务）</td><td>${r.m.completionTime===null?'未全部按期完成':'T+'+r.m.completionTime}</td><td>${r.m.spent}</td><td>${r.index===null?'—':r.index.toFixed(3)}<small>作者T+${r.ref.completionTime} / 投入${r.ref.spent}</small></td></tr>`).join('')}</tbody></table></div><p class="hint">先比较按期完成权重比例；双方全部完成后，再比较0.6×(解题用时+1)/(作者用时+1)＋0.4×(解题投入+1)/(作者投入+1)，越低越优。加1用于处理零投入。不同脚本难度不能完全等同，该指数用于同伴讨论，不替代统一试题成绩。</p>`;}
 function view(){const m=store.match,active=store.active,base=U.getState(),ready=store.own?.referenceState;return `<section class="decision-intro"><span class="eyebrow">RECIPROCAL CHALLENGE / 双向脚本对战</span><h2>你出一道题，我来解决；再交换角色</h2><p>双方编排事件、地点、需求和投放时刻，先自测证明可解，再交换脚本与处置战报。当前支持JSON文件交换的异步对战；不需要同时在线。此处使用协作脚本与资源体系，和教学道路实验分别记录。</p></section>${loadError?'<div class="notice">本机对战记录无法校验，原存储仍保留；可重新导入对战邀请和题包建立本轮。</div>':''}<section class="panel"><div class="panel-head"><h2>1 · 约定双方与对战</h2>${btn('导入邀请 / 题包 / 战报','import')}</div><div class="panel-body">${m?`<div class="duel-match"><b>${e(m.title)}</b><span class="tag">${e(m.id)}</span><p>A方：${e(m.teams.A)} · B方：${e(m.teams.B)}；本机身份：<b>${e(team(store.side))}</b></p><div class="actions">${btn('导出对战邀请','invite-export')}${btn('新建另一场对战','create','', 'subtle')}</div></div>`:`<p class="hint">由A方创建邀请，B方导入同一邀请。已有邀请时直接导入，不要双方各自创建不同编号。</p>${btn('创建对战邀请','create','','primary')}`}</div></section><input type="file" id="duel-import-file" accept="application/json,.json" hidden>${m?`<div class="two-col spaced"><section class="panel"><div class="panel-head"><h2>2 · 本方出题与自测</h2><span class="tag">${ready?'已通过自测':'待自测'}</span></div><div class="panel-body"><p class="hint">先到情景脚本编排流程；可在资源与题库编辑任务、资源、工期与需求。对战发布后条件固定。</p><div class="actions"><button data-nav="command-scripts">编辑情景脚本</button><button data-nav="command-library">编辑任务与资源</button></div><label class="field spaced">选择本方脚本<select id="duel-script">${base.library.scripts.map(s=>`<option value="${e(s.id)}">${e(s.name)}</option>`).join('')}</select></label><div class="actions spaced">${btn('开始作者自测','author-start',active?'disabled':'','primary')}${btn('导出本方题包','question-export',ready?'':'disabled')}</div>${ready?`<p class="hint">已发布版本：${e(store.own.library.scripts[0].name)}；自测首次完成T+${metrics(store.own,ready).completionTime}。重新自测会生成新题目编号，需重新交换题包与战报。</p>`:''}</div></section><section class="panel"><div class="panel-head"><h2>3 · 解决对方脚本</h2><span class="tag">${store.opponent?'已收到题包':'待交换'}</span></div><div class="panel-body"><p>${store.opponent?e(store.opponent.library.scripts[0].name):'等待对方自测后导出题包，在这里导入。'}</p><p class="hint">开始前保存当前协作演练，再在独立轮次中解决对方所有任务。未到投放时间的节点也计入目标，不能提前结束绕过。</p><div class="actions">${btn('导入对方题包','import')}${btn('开始解对方脚本','challenge-start',store.opponent&&!active?'':'disabled','primary')}${btn('导出我的解题战报','result-export',store.ownResult?'':'disabled')}</div></div></section></div>${active?`<section class="panel spaced"><div class="panel-head"><h2>当前轮次 · ${active.kind==='author'?'作者自测':'解对方脚本'}</h2></div><div class="panel-body"><p>${current()?`当前T+${base.time} · ${base.run.status==='ended'?'已结束，等待封存':'进行中'}`:'当前打开的演练与保存的对战轮次不同，可恢复本轮。'}</p><div class="actions"><button data-nav="command-dispatch">继续力量派遣</button>${btn('恢复本轮进度','resume')}${btn('结束并封存本轮','finish','','primary')}${btn('退出本轮（保留协作记录）','leave','','subtle')}</div></div></section>`:''}<section class="panel spaced"><div class="panel-head"><h2>4 · 双向战报与复盘</h2><div class="actions">${btn('导入对方战报','import')}${btn('导出对战对照报告','report',store.ownResult&&store.opponentResult?'':'disabled')}</div></div><div class="panel-body">${scoreboard()}</div></section>`:''}<p class="hint spaced">对战文件包含教学脚本及验证记录，适合同伴互练；本机文件可编辑，不作为保密或防篡改考试成绩。现有多人协作房间继续独立使用。</p>`;}
 function confirm(title,body,action,value){pending={action,value};window.modal(`<h2>${e(title)}</h2><p>${e(body)}</p><div class="actions">${btn('确认继续','confirm','','primary')}<button data-action="close-dialog">取消</button></div>`);}
 function exportJson(name,value){window.download(name,JSON.stringify(value,null,2),'application/json');}
 async function handle(action){
  if(action==='import'){document.querySelector('#duel-import-file').click();return;}
  if(action==='create'){local();window.modal(`<h2>创建双向脚本对战</h2><p>创建后把邀请JSON交给B方；已有本场题包或战报时，请先导出保存。</p><form id="duel-create-form"><label class="field">对战名称<input name="title" maxlength="80" value="双向脚本挑战" required></label><div class="form-grid"><label class="field">A方队名<input name="A" maxlength="40" value="第一小组" required></label><label class="field">B方队名<input name="B" maxlength="40" value="第二小组" required></label></div><button class="primary spaced" type="submit">创建并作为A方加入</button></form>`);return;}
  if(action==='confirm'){local();const item=pending;assert(item,'请重新选择操作');if(item.action==='begin')begin(item.value.kind,item.value.scriptId);if(item.action==='import'){commit(item.value);window.navigate('command-duel');}if(item.action==='create'){commit(item.value);window.navigate('command-duel');}if(item.action==='leave'){if(current()&&['running','paused'].includes(U.getState().run.status))assert(await U.dispatch({type:'run-end'}),'无法结束当前轮次');const next=copy(store);next.active=null;commit(next);window.navigate('command-duel');}pending=null;document.querySelector('#dialog').close();return;}
  if(action==='author-start'||action==='challenge-start'){local();confirm('开始独立对战轮次','当前协作演练将先存档。对战使用固定脚本与资源，从T+0开始；如重新自测，本方旧题包与收到的旧战报将被替换，请先导出重要记录。','begin',{kind:action==='author-start'?'author':'challenge',scriptId:document.querySelector('#duel-script').value});return;}
  if(action==='invite-export'){assert(store.match,'请先创建对战');exportJson('对战邀请-'+store.match.id+'.json',{kind:'flood-script-duel-invite',version:1,match:store.match});}
  if(action==='question-export'){const p=validatePacket(store.own);exportJson('对战题包-'+team(store.side)+'.json',p);}
  if(action==='result-export'){assert(store.ownResult,'请先封存解题结果');exportJson('解题战报-'+team(store.side)+'.json',store.ownResult);}
  if(action==='resume'){local();assert(store.active,'没有可恢复轮次');U.loadLocal(store.active.state);window.navigate('command');}
  if(action==='finish')await finish();
  if(action==='leave')confirm('退出当前对战轮次','将结束当前轮次，保留协作实践记录。本轮尚未封存时不会生成有效题包或战报。','leave');
  if(action==='report'){assert(store.ownResult&&store.opponentResult,'请先交换双方战报');window.download('双向脚本对战报告.html',`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>双向脚本对战报告</title><style>body{font:15px/1.9 sans-serif;max-width:1000px;margin:40px auto;padding:20px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #aaa;padding:10px;text-align:left}small{display:block}</style><h1>${e(store.match.title)}</h1><p>对战编号${e(store.match.id)}；A方${e(store.match.teams.A)}；B方${e(store.match.teams.B)}</p>${scoreboard()}<p>脚本和原始处置证据分别保存在双方题包与解题战报JSON中。此为异步教学对照。</p></html>`,'text/html;charset=utf-8');}
 }
 async function importFile(raw){local();assert(raw&&typeof raw==='object'&&!Array.isArray(raw),'请选择有效的对战JSON文件');assert(!store.active,'请先封存或退出当前轮次，再导入对战文件');let next=copy(store);
  if(raw.kind==='flood-script-duel-invite'){assert(raw.version===1,'邀请版本不支持');next=empty();next.match=validateMatch(raw.match);next.side='B';confirm('以B方加入邀请','导入后本机作为B方加入。当前对战记录将替换，请先导出重要题包和战报。','import',next);return;}
  assert(store.match,'请先导入同一场对战邀请');
  if(raw.kind==='flood-script-duel-challenge'){const p=validatePacket(raw);assert(stable(p.match)===stable(store.match)&&p.author===opposite(store.side),'题包不属于当前对手或本场对战');next.opponent=p;next.ownResult=null;confirm('接收对方脚本','将替换之前接收的对方脚本及对应的本方解题战报。不会立即启动或改写当前协作演练。','import',next);return;}
  if(raw.kind==='flood-script-duel-result'){assert(store.own?.referenceState,'请先完成本方自测并发布题包');next.opponentResult=result(store.own,raw,opposite(store.side));commit(next);window.navigate('command-duel');window.toast?.('对方战报已校验并接收');return;}
  throw Error('请选择对战邀请、对战题包或解题战报JSON；普通实验和题库备份不能在这里导入');
 }
 document.addEventListener('click',event=>{const b=event.target.closest('[data-duel]');if(!b||b.disabled)return;handle(b.dataset.duel).catch(err=>window.toast?.(err.message));});
 document.addEventListener('submit',event=>{if(event.target.id!=='duel-create-form')return;event.preventDefault();try{local();assert(!store.active,'请先封存或退出当前对战轮次');const f=new FormData(event.target),next=empty();next.match=validateMatch({id:uid('duel'),title:String(f.get('title')).trim(),teams:{A:String(f.get('A')).trim(),B:String(f.get('B')).trim()},rules:1});confirm('创建新的对战','本机作为A方。已有本场对战记录会被替换，请先导出重要题包和战报。','create',next);}catch(err){window.toast?.(err.message);}});
 document.addEventListener('change',async event=>{if(event.target.id!=='duel-import-file')return;const file=event.target.files?.[0];if(!file)return;try{assert(file.size<=12*1024*1024,'对战文件不能超过12MB');await importFile(JSON.parse(await file.text()));}catch(err){window.toast?.(err instanceof SyntaxError?'文件不是有效JSON':err.message);}event.target.value='';});
 return {view,banner,guard,observe,validatePacket,metrics,importFile,isActive:current,getStore:()=>copy(store)};
})();
